SELECT COLUMN_NAME, DATA_TYPE FROM information_schema.COLUMNS WHERE TABLE_SCHEMA='crypto_ai' AND TABLE_NAME='trade_signal' AND COLUMN_NAME IN ('atr_at_signal','atr_percent','volatility_level','candle_range_atr_multiple','atr_overextended','atr_immediate_entry_allowed','atr_retracement_entry_price','liquidity_status','entry_authority','entry_authority_max_position_percent','atr_explanation') ORDER BY COLUMN_NAME;
SELECT id, symbol, interval_code, decision, latest_price, stop_loss, take_profit, risk_reward_ratio, atr_at_signal, atr_percent, volatility_level, candle_range_atr_multiple, atr_overextended, atr_entry_type, atr_recommended_position_percent, atr_immediate_entry_allowed, atr_retracement_entry_price, market_regime, LEFT(atr_explanation, 300) AS atr_explanation FROM crypto_ai.trade_signal WHERE id IN (156723,159408,159285,165412,165415,167668,167616,171589,171559,176710,176655) ORDER BY symbol, generated_at;